import * as THREE from 'three/webgpu';
import { color, float, uniform, vec3, mix, clamp } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

const CAPTIONS = [
  'DIAL ROOM',
  'ESCAPEMENT BENCH',
  'CNC HALL',
  'FINISHING LAB',
  'ARCHIVE VAULT',
  'ASSEMBLY LINE ONE',
];

const PLATE_W = 1.9;
const PLATE_H = 1.2;
const PITCH = 1.5;
const COUNT = 6;
const LOOP_LEN = 9.0;
const COL_X = 0.9;
const BEVEL = 0.03;

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const baseTexture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  baseTexture.colorSpace = THREE.SRGBColorSpace;

  const column = new THREE.Group();
  column.position.x = COL_X;
  group.add(column);

  // header
  const header = createText(ctx.fontAtlas, {
    text: 'Inside the atelier',
    fontSize: 68,
    family: 'Lora',
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
  });
  header.position.set(-1.6, 1.9, 0);
  group.add(header);

  const plates = [];
  const disposables = [];
  const accentUniforms = [];

  for (let i = 0; i < COUNT; i++) {
    const plateGroup = new THREE.Group();
    const baseY = i * PITCH - (COUNT * PITCH) / 2;
    plateGroup.userData.baseY = baseY;
    plateGroup.position.y = baseY;

    // slight variant tint per plate to simulate distinct photograph crops
    const hueShift = new THREE.Color().setHSL((i * 0.07) % 1, 0.15, 0.5 + (i % 3) * 0.03);
    const geo = new THREE.PlaneGeometry(PLATE_W, PLATE_H);
    const mat = new THREE.MeshPhysicalNodeMaterial();
    mat.map = baseTexture;
    mat.roughness = 0.6;
    mat.metalness = 0.1;
    mat.clearcoat = 0.1;
    mat.colorNode = color(baseTexture).mul(color(hueShift.getHex()));
    const plate = new THREE.Mesh(geo, mat);
    plateGroup.add(plate);
    disposables.push(geo, mat);

    // bevel frame (machined ink, brushed edge highlight)
    const frameGeo = new THREE.PlaneGeometry(PLATE_W + BEVEL * 2, PLATE_H + BEVEL * 2);
    const frameMat = new THREE.MeshStandardNodeMaterial();
    frameMat.color = new THREE.Color('#16161d');
    frameMat.roughness = 0.5;
    frameMat.metalness = 0.5;
    const frame = new THREE.Mesh(frameGeo, frameMat);
    frame.position.z = -0.001;
    plateGroup.add(frame);
    disposables.push(frameGeo, frameMat);

    // accent strip
    const accentGeo = new THREE.PlaneGeometry(BEVEL, PLATE_H);
    const accentUniform = uniform(0.0);
    const accentMat = new THREE.MeshStandardNodeMaterial();
    accentMat.color = new THREE.Color('#ff2a38');
    accentMat.emissiveNode = color('#ff2a38').mul(accentUniform);
    accentMat.emissive = new THREE.Color('#ff2a38');
    const accent = new THREE.Mesh(accentGeo, accentMat);
    accent.position.set(-PLATE_W / 2 - BEVEL / 2, 0, 0.002);
    plateGroup.add(accent);
    accentUniforms.push(accentUniform);
    disposables.push(accentGeo, accentMat);

    // caption
    const caption = createText(ctx.fontAtlas, {
      text: CAPTIONS[i % CAPTIONS.length],
      fontSize: 18,
      family: 'JetBrains Mono',
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: '#e8ecf2',
    });
    caption.position.set(-1.6 - COL_X, 0, 0.01);
    caption.material.transparent = true;
    caption.material.opacity = 0;
    plateGroup.add(caption);

    plateGroup.userData.plate = plate;
    plateGroup.userData.caption = caption;
    plateGroup.userData.accentUniform = accentUniform;
    plates.push(plateGroup);
    column.add(plateGroup);
  }

  // scroll-driven loop state
  const state = {
    scrollY: 0,
    targetScrollY: 0,
  };

  const camDolly = { z: 0 };
  const timelines = [];

  function findFocused() {
    let closest = null;
    let closestDist = Infinity;
    for (const p of plates) {
      let y = p.userData.baseY - state.scrollY;
      y = ((y + LOOP_LEN / 2) % LOOP_LEN + LOOP_LEN) % LOOP_LEN - LOOP_LEN / 2;
      p.position.y = y;
      const dist = Math.abs(y);
      if (dist < closestDist) {
        closestDist = dist;
        closest = p;
      }
    }
    return closest;
  }

  let focusedPlate = null;

  function updateFocus() {
    const newFocused = findFocused();
    if (newFocused !== focusedPlate) {
      if (focusedPlate) {
        const tl = gsap.timeline();
        tl.to(focusedPlate.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.35, ease: 'power2.out' });
        tl.to(focusedPlate.userData.accentUniform, { value: 0.0, duration: 0.35 });
        tl.to(focusedPlate.userData.caption.material, { opacity: 0, duration: 0.35 });
        timelines.push(tl);
      }
      focusedPlate = newFocused;
      if (focusedPlate) {
        const tl = gsap.timeline();
        tl.to(focusedPlate.scale, {
          x: 1.06,
          y: 1.06,
          z: 1.06,
          duration: 0.35,
          ease: 'cubic-bezier(0.215,0.61,0.355,1)',
        });
        tl.to(focusedPlate.userData.accentUniform, { value: 1.4, duration: 0.35 });
        tl.to(focusedPlate.userData.caption.material, {
          opacity: 1,
          duration: 0.4,
          ease: 'power2.out',
        });
        focusedPlate.userData.caption.position.x = -1.6 - COL_X - 0.1;
        gsap.fromTo(
          focusedPlate.userData.caption.position,
          { x: -1.6 - COL_X - 0.1 },
          { x: -1.6 - COL_X, duration: 0.4, ease: 'power2.out' }
        );
        timelines.push(tl);
      }
    }
  }

  updateFocus();

  // apply fly-through primitive
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        ctx.primitives[prim.name](group, prim.params);
      }
    }
  }

  let scrollInertia = { current: 0, target: 0 };

  const handleScroll = (delta) => {
    state.targetScrollY += delta * PITCH;
  };

  let rafActive = true;
  function tick() {
    if (!rafActive) return;
    const damping = 0.12;
    state.scrollY += (state.targetScrollY - state.scrollY) * damping;
    updateFocus();
    camDolly.z = (state.scrollY / LOOP_LEN) * 2.5;
    requestAnimationFrame(tick);
  }
  tick();

  group.userData.handlers = {
    onWheel: (e) => {
      handleScroll(Math.sign(e.deltaY || 1));
    },
    onScroll: (delta) => {
      handleScroll(delta);
    },
  };

  group.userData.cleanup = () => {
    rafActive = false;
    for (const tl of timelines) tl.kill();
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    baseTexture.dispose();
    if (header.material) header.material.dispose();
    if (header.geometry) header.geometry.dispose();
    for (const p of plates) {
      const cap = p.userData.caption;
      if (cap.material) cap.material.dispose();
      if (cap.geometry) cap.geometry.dispose();
    }
  };

  return group;
}
